insert into public.eventos (nombre, lugar, info, orden) values ('ICONS', 'Card show', 'Buy · Sell · Trade', 3);
insert into public.eventos (nombre, lugar, info, orden) values ('Quedadas locales', 'Comunidad Valenciana', 'Plaza Ayto. San Antonio de Benagéber', 4);
insert into public.faq (pregunta, respuesta, orden) values ('¿Vendéis por la web?', 'No. La web muestra el stock disponible en tienda. Para reservar algo escríbenos por Instagram y te lo guardamos. Las ventas online van por Cardmarket.', 0);
insert into public.faq (pregunta, respuesta, orden) values ('¿Compráis colecciones?', 'Sí. Compramos cartas gradeadas, producto sellado y cartas sueltas. Mándanos fotos por DM y te hacemos oferta.', 1);
insert into public.faq (pregunta, respuesta, orden) values ('¿Hacéis intercambios?', 'Buy · Sell · Trade worldwide. Si tienes algo interesante, hablamos.', 2);
insert into public.faq (pregunta, respuesta, orden) values ('¿Las gradeadas están a la venta?', 'Algunas sí y otras son de colección. Pregunta por la que te interese indicando el nº de certificado.', 3);
insert into public.faq (pregunta, respuesta, orden) values ('¿Enviáis fuera de España?', 'Sí, a través de Cardmarket enviamos a toda Europa.', 4);
insert into public.ajustes (clave, valor) values ('sobre_mi_1', 'Soy Edu, de Valencia. Abrí mi primer sobre de pequeño y nunca he parado. Kai Collect nace de eso: de las ganas de compartir esta afición con gente que la vive igual que yo.') on conflict (clave) do update set valor = excluded.valor;
insert into public.ajustes (clave, valor) values ('sobre_mi_2', 'Hoy nos dedicamos a comprar, vender e intercambiar Pokémon TCG por todo el mundo: producto sellado, cartas sueltas y gradeadas top. Nos verás en card shows de España y Europa, haciendo sorteos y abriendo sobres en directo.') on conflict (clave) do update set valor = excluded.valor;
insert into public.ajustes (clave, valor) values ('cita', '会 (kai) significa reunión, encuentro. Eso es esta tienda: un sitio donde se junta la comunidad.') on conflict (clave) do update set valor = excluded.valor;
insert into public.ajustes (clave, valor) values ('direccion', 'Kai Collect · Valencia, España') on conflict (clave) do update set valor = excluded.valor;
insert into public.ajustes (clave, valor) values ('horario', '') on conflict (clave) do update set valor = excluded.valor;
insert into public.ajustes (clave, valor) values ('aviso', '') on conflict (clave) do update set valor = excluded.valor;
insert into public.ajustes (clave, valor) values ('actualizado', '24 nov 2026') on conflict (clave) do update set valor = excluded.valor;
